import raw from './attack-enterprise.json';

/**
 * MITRE ATT&CK Enterprise reference data for Sigma tags.
 *
 * This is a compact, versioned subset generated by
 * `scripts/build-attack-data.mjs` from the ATT&CK STIX bundle. It is loaded
 * only when the tag picker opens. Nothing here fetches updates at runtime.
 */

export const ATTACK_DATASET_SCHEMA_VERSION = 1;
export const ATTACK_MAX_SEARCH_RESULTS = 100;
export const ATTACK_MAX_RULE_TAGS = 100;

export interface AttackTactic {
  id: string;
  name: string;
  shortName: string;
}

export interface AttackTechnique {
  id: string;
  name: string;
  tactics: string[];
  subtechnique: boolean;
}

export interface AttackDataset {
  schemaVersion: number;
  attackVersion: string;
  retrieved: string;
  source: string;
  sourcePath: string;
  sourceSha256: string;
  license: string;
  tactics: AttackTactic[];
  techniques: AttackTechnique[];
}

export interface AttackSearchOptions {
  tactic?: string;
  limit?: number;
}

export type AttackTagInfo =
  | { kind: 'tactic'; tag: string; tactic: AttackTactic }
  | { kind: 'technique'; tag: string; technique: AttackTechnique }
  | { kind: 'unknown'; tag: string };

export class AttackDataError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'AttackDataError';
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function cleanText(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

/**
 * Accept only well-formed tactics and techniques. A corrupt or partial
 * vendored file should leave a usable picker rather than crash the view.
 */
export function normalizeAttackDataset(value: unknown): AttackDataset {
  if (!isRecord(value)) throw new AttackDataError('The ATT&CK dataset is not an object.');
  if (value.schemaVersion !== ATTACK_DATASET_SCHEMA_VERSION) {
    throw new AttackDataError(
      `Unsupported ATT&CK dataset schema version: ${String(value.schemaVersion)}.`,
    );
  }

  const tactics: AttackTactic[] = [];
  const tacticIds = new Set<string>();
  const tacticNames = new Set<string>();
  if (Array.isArray(value.tactics)) {
    for (const item of value.tactics) {
      if (!isRecord(item)) continue;
      const id = cleanText(item.id);
      const name = cleanText(item.name);
      const shortName = cleanText(item.shortName);
      if (!id || !name || !shortName) continue;
      if (tacticIds.has(id) || tacticNames.has(shortName)) continue;
      tacticIds.add(id);
      tacticNames.add(shortName);
      tactics.push({ id, name, shortName });
    }
  }

  const techniques: AttackTechnique[] = [];
  const techniqueIds = new Set<string>();
  if (Array.isArray(value.techniques)) {
    for (const item of value.techniques) {
      if (!isRecord(item)) continue;
      const id = cleanText(item.id);
      const name = cleanText(item.name);
      if (!id || !name || techniqueIds.has(id)) continue;
      const itemTactics = Array.isArray(item.tactics)
        ? [
            ...new Set(
              item.tactics
                .map(cleanText)
                .filter((tactic): tactic is string => tactic !== null && tacticNames.has(tactic)),
            ),
          ]
        : [];
      if (itemTactics.length === 0) continue;
      techniqueIds.add(id);
      techniques.push({
        id,
        name,
        tactics: itemTactics,
        subtechnique: item.subtechnique === true,
      });
    }
  }

  const attackVersion = cleanText(value.attackVersion);
  if (!attackVersion) throw new AttackDataError('The ATT&CK dataset has no version.');

  return {
    schemaVersion: ATTACK_DATASET_SCHEMA_VERSION,
    attackVersion,
    retrieved: cleanText(value.retrieved) ?? '',
    source: cleanText(value.source) ?? '',
    sourcePath: cleanText(value.sourcePath) ?? '',
    sourceSha256: cleanText(value.sourceSha256) ?? '',
    license: cleanText(value.license) ?? '',
    tactics,
    techniques,
  };
}

export const ATTACK_DATASET: AttackDataset = normalizeAttackDataset(raw);

/** Convert a technique id such as `T1059.001` to the Sigma tag form. */
export function attackTechniqueTag(id: string): string {
  const cleaned = id.trim().toLowerCase();
  return cleaned.length > 0 ? `attack.${cleaned}` : '';
}

/** Convert a tactic short name such as `execution` to the Sigma tag form. */
export function attackTacticTag(shortName: string): string {
  const cleaned = shortName.trim().toLowerCase();
  return cleaned.length > 0 ? `attack.${cleaned}` : '';
}

export function describeAttackTag(
  tag: string,
  dataset: AttackDataset = ATTACK_DATASET,
): AttackTagInfo {
  const cleaned = tag.trim().toLowerCase();
  if (!cleaned.startsWith('attack.')) return { kind: 'unknown', tag };

  const value = cleaned.slice('attack.'.length);
  const technique = dataset.techniques.find((entry) => entry.id.toLowerCase() === value);
  if (technique) return { kind: 'technique', tag: cleaned, technique };

  const tactic =
    dataset.tactics.find((entry) => entry.shortName.toLowerCase() === value) ??
    dataset.tactics.find((entry) => entry.id.toLowerCase() === value);
  if (tactic) return { kind: 'tactic', tag: cleaned, tactic };

  return { kind: 'unknown', tag };
}

export function isAttackTag(tag: string): boolean {
  return describeAttackTag(tag).kind !== 'unknown';
}

export function searchAttackTechniques(
  query: string,
  options: AttackSearchOptions = {},
  dataset: AttackDataset = ATTACK_DATASET,
): AttackTechnique[] {
  const needle = query.trim().toLowerCase();
  const tactic = options.tactic?.trim().toLowerCase() ?? '';
  const limit = Math.min(
    ATTACK_MAX_SEARCH_RESULTS,
    Math.max(1, Math.floor(options.limit ?? 50)),
  );

  const matches = dataset.techniques.filter((technique) => {
    if (tactic && !technique.tactics.includes(tactic)) return false;
    if (needle.length === 0) return true;
    return (
      technique.id.toLowerCase().includes(needle) ||
      technique.name.toLowerCase().includes(needle) ||
      technique.tactics.some((name) => name.includes(needle))
    );
  });

  if (needle.length === 0) return matches.slice(0, limit);

  const score = (technique: AttackTechnique): number => {
    const id = technique.id.toLowerCase();
    const name = technique.name.toLowerCase();
    if (id === needle) return 0;
    if (id.startsWith(needle)) return 1;
    if (name.startsWith(needle)) return 2;
    if (id.includes(needle)) return 3;
    if (name.includes(needle)) return 4;
    return 5;
  };

  return matches
    .sort((left, right) => score(left) - score(right) || left.id.localeCompare(right.id))
    .slice(0, limit);
}

export function techniquesForTactic(
  shortName: string,
  dataset: AttackDataset = ATTACK_DATASET,
): AttackTechnique[] {
  const tactic = shortName.trim().toLowerCase();
  if (tactic.length === 0) return [];
  return dataset.techniques.filter((technique) => technique.tactics.includes(tactic));
}

/**
 * Merge tags without duplicating an existing tag. The rule cap keeps a picker
 * session from producing an unbounded tags list.
 */
export function mergeAttackTags(
  existing: readonly string[],
  additions: readonly string[],
  limit = ATTACK_MAX_RULE_TAGS,
): string[] {
  const merged: string[] = [];
  const seen = new Set<string>();
  for (const value of [...existing, ...additions]) {
    if (typeof value !== 'string') continue;
    const tag = value.trim();
    if (tag.length === 0 || seen.has(tag)) continue;
    seen.add(tag);
    merged.push(tag);
  }
  if (merged.length > limit) {
    throw new AttackDataError(
      `A rule can carry at most ${limit} tags; remove one before adding another.`,
    );
  }
  return merged;
}

export function removeAttackTag(tags: readonly string[], tag: string): string[] {
  return tags.filter((entry) => entry !== tag);
}

export function attackTagName(info: AttackTagInfo): string {
  if (info.kind === 'technique') return `${info.technique.id} · ${info.technique.name}`;
  if (info.kind === 'tactic') return `${info.tactic.id} · ${info.tactic.name}`;
  return info.tag;
}

export function attackDatasetFingerprint(dataset: AttackDataset = ATTACK_DATASET): string {
  return dataset.sourceSha256.slice(0, 16);
}
